insert into tm_rooms (id, scale, code, name, intro, sort_order, i18n) values
  ('P1', 'small', 'Team 1', 'Product team', 'Đây là chỗ của bạn. Product Manager quyết định làm gì và theo thứ tự nào, bạn thiết kế, Intern học cùng bạn. Ở công ty nhỏ, designer thường kiêm luôn research và viết nội dung giao diện.', 0, '{"en": {"code": "Team 1", "name": "Product team", "intro": "This is your spot. The Product Manager decides what to build and in what order, you design, and the Intern learns alongside you. In a small company, designers often handle research and interface copy too."}}'::jsonb),
  ('P2', 'small', 'Team 2', 'Dev team', 'Tech Lead, Frontend, Backend, Mobile và QA biến thiết kế thành sản phẩm chạy được. Bạn sẽ sang đây để handoff, trả lời câu hỏi và review bản build.', 1, '{"en": {"code": "Team 2", "name": "Dev team", "intro": "The Tech Lead, Frontend, Backend, Mobile and QA turn designs into a working product. You come here to hand off, answer questions and review builds."}}'::jsonb),
  ('P3', 'small', 'Team 3', 'Business team', 'CEO, Marketing, Sales, Customer Support và Business Analyst. Nơi đặt mục tiêu kinh doanh và nghe tiếng nói khách hàng, nguồn insight quý cho thiết kế.', 2, '{"en": {"code": "Team 3", "name": "Business team", "intro": "The CEO, Marketing, Sales, Customer Support and the Business Analyst. This is where business goals are set and the customer''s voice is heard, a valuable source of insight for design."}}'::jsonb),
  ('P4', 'small', 'Họp', 'Phòng họp', 'Phòng dùng cho Sprint Planning, demo cuối sprint và các buổi họp cả công ty. TV để trình bày thiết kế.', 3, '{"en": {"code": "Meeting", "name": "Meeting room", "intro": "Used for Sprint Planning, end-of-sprint demos and company-wide meetings. The TV is for presenting designs."}}'::jsonb),
  ('P5', 'small', 'Chung', 'Pantry', 'Khu chung để nghỉ, gặp gỡ ngẫu nhiên và sinh hoạt guild. Nhiều ý tưởng hay bắt đầu từ một cuộc nói chuyện ở đây.', 4, '{"en": {"code": "Shared", "name": "Pantry", "intro": "A shared space for breaks, chance encounters and guild meetups. Many good ideas start with a chat here."}}'::jsonb),
  ('P6', 'small', 'Đóng', 'Phòng ban khác', null, 5, '{"en": {"code": "Closed", "name": "Other departments"}}'::jsonb),
  ('R01', 'large', 'R01', 'Leadership', 'CEO, CPO, CTO và các Head. Đặt chiến lược và OKR cho cả công ty. Head of Design là quản lý chuyên môn cao nhất của bạn.', 0, '{"en": {"code": "R01", "name": "Leadership", "intro": "The CEO, CPO, CTO and the Heads. They set strategy and OKRs for the whole company. The Head of Design is your most senior craft manager."}}'::jsonb),
  ('R07', 'large', 'R07', 'Data & Analytics', 'Data Analyst, BI Analyst, Data Scientist và Data Engineer. Ghé đây khi cần số liệu funnel hay kết quả A/B test.', 1, '{"en": {"code": "R07", "name": "Data & Analytics", "intro": "Data Analyst, BI Analyst, Data Scientist and Data Engineer. Drop by when you need funnel numbers or A/B test results."}}'::jsonb),
  ('R08', 'large', 'R08', 'Phòng họp', 'Sprint Planning và Sprint Review diễn ra ở đây. Stakeholder thường tới dự buổi demo.', 2, '{"en": {"code": "R08", "name": "Meeting room", "intro": "Sprint Planning and Sprint Review happen here. Stakeholders often come to the demo."}}'::jsonb),
  ('R02', 'large', 'R02', 'Tribe Growth', 'Các squad lo onboarding, kích hoạt và giới thiệu bạn bè. Designer ở đây làm việc nhiều với A/B test và số liệu tăng trưởng.', 3, '{"en": {"code": "R02", "name": "Tribe Growth", "intro": "The squads behind onboarding, activation and referrals. Designers here work a lot with A/B tests and growth metrics."}}'::jsonb),
  ('R03', 'large', 'R03', 'Core Experience', 'Squad của bạn: PM, designer, Tech Lead, dev và QA ngồi chung một bàn. Đây là nơi bạn làm việc hằng ngày.', 4, '{"en": {"code": "R03", "name": "Core Experience", "intro": "Your squad: the PM, designers, Tech Lead, developers and QA share one table. This is where you work every day."}}'::jsonb),
  ('R04', 'large', 'R04', 'Monetization', 'Squad lo thanh toán và gói dịch vụ. Designer ở đây làm việc sát với các ràng buộc về giá và pháp lý.', 5, '{"en": {"code": "R04", "name": "Monetization", "intro": "The squad behind payments and plans. Designers here work closely with pricing and legal constraints."}}'::jsonb),
  ('R05', 'large', 'R05', 'Platform', 'DevOps, Software Architect và team Design System. Hỏi team Design System trước khi vẽ một component mới.', 6, '{"en": {"code": "R05", "name": "Platform", "intro": "DevOps, the Software Architect and the Design System team. Ask the Design System team before drawing a new component."}}'::jsonb),
  ('R06', 'large', 'R06', 'Design Studio', 'Ngôi nhà chuyên môn của designer: Design Manager, UX Researcher, UX Writer, Motion Designer. Buổi Design Critique diễn ra hằng tuần ở đây.', 7, '{"en": {"code": "R06", "name": "Design Studio", "intro": "The craft home for designers: Design Manager, UX Researcher, UX Writer, Motion Designer. Design Critique happens here every week."}}'::jsonb),
  ('R09', 'large', 'R09', 'Delivery Hub', 'Scrum Master, Delivery Manager và Project Manager giữ nhịp sprint và hạn chót phát hành.', 8, '{"en": {"code": "R09", "name": "Delivery Hub", "intro": "The Scrum Master, Delivery Manager and Project Manager keep the sprint rhythm and the release deadlines."}}'::jsonb),
  ('R11', 'large', 'Chung', 'Pantry', 'Khu chung để nghỉ, gặp gỡ ngẫu nhiên và sinh hoạt guild. Người dùng được mời tới phỏng vấn cũng hay ngồi chờ ở đây.', 9, '{"en": {"code": "Shared", "name": "Pantry", "intro": "A shared space for breaks, chance encounters and guild meetups. Users invited for interviews often wait here too."}}'::jsonb),
  ('R10', 'large', 'R10', 'Hàng xóm · ngoài vách kính', 'Marketing, Customer Success, Sales và Business Analyst ngồi ngoài vách kính. Họ là những stakeholder bạn làm việc cùng thường xuyên.', 10, '{"en": {"code": "R10", "name": "Neighbours · behind the glass", "intro": "Marketing, Customer Success, Sales and the Business Analyst sit behind the glass wall. They are the stakeholders you work with most often."}}'::jsonb),
  ('A1', 'agency', 'Team 1', 'Design team', 'Ở agency bạn làm nhiều dự án cùng lúc, mỗi dự án một ngành khác nhau. Học nhanh và rộng, nhưng ít khi theo một sản phẩm đủ lâu để thấy kết quả. Người duyệt thiết kế của bạn là Design Director.', 0, '{"en": {"code": "Team 1", "name": "Design team", "intro": "At an agency you work on several projects at once, each in a different industry. You learn fast and wide, but rarely stay on one product long enough to see the results. Your designs are approved by the Design Director."}}'::jsonb),
  ('A2', 'agency', 'Team 2', 'Dev team', 'Một dev ở đây có thể chạy 2–3 dự án cùng lúc và thường không dự các buổi họp với khách. File thiết kế của bạn phải tự nói được mọi thứ.', 1, '{"en": {"code": "Team 2", "name": "Dev team", "intro": "A developer here may run 2–3 projects at once and usually skips client meetings. Your design files have to explain everything on their own."}}'::jsonb),
  ('A3', 'agency', 'Team 3', 'Account & Project', 'Mọi yêu cầu của khách hàng đi qua đây. Account Manager giữ quan hệ, Project Manager giữ phạm vi, tiến độ và ngân sách. Đừng tự hứa gì với khách khi chưa hỏi Project Manager.', 2, '{"en": {"code": "Team 3", "name": "Account & Project", "intro": "Every client request goes through here. The Account Manager owns the relationship, the Project Manager owns scope, schedule and budget. Never promise the client anything before checking with the Project Manager."}}'::jsonb),
  ('A4', 'agency', 'Họp', 'Phòng họp khách hàng', 'Nơi trình bày concept và nghe phản hồi của khách. Thiết kế tốt mà trình bày không rõ thì vẫn bị bác: ở agency, kỹ năng thuyết trình quan trọng ngang kỹ năng vẽ.', 3, '{"en": {"code": "Meeting", "name": "Client meeting room", "intro": "Where concepts are presented and client feedback is heard. A good design that is presented badly still gets rejected: at an agency, presenting matters as much as designing."}}'::jsonb),
  ('A5', 'agency', 'Chung', 'Pantry', 'Khu chung để nghỉ và gặp gỡ. Người dùng được mời tới dùng thử sản phẩm của khách cũng ngồi chờ ở đây.', 4, '{"en": {"code": "Shared", "name": "Pantry", "intro": "A shared space for breaks and meetups. Users invited to try the client''s product wait here too."}}'::jsonb),
  ('A6', 'agency', 'Team 4', 'Sales', 'Nơi mang dự án về cho công ty. Designer hay được nhờ dựng nhanh một bản demo để Sales đi thuyết phục khách ký hợp đồng.', 5, '{"en": {"code": "Team 4", "name": "Sales", "intro": "Where projects come into the company. Designers are often asked to put together a quick demo so Sales can convince clients to sign."}}'::jsonb)
insert into tm_characters (id, title, kind, "group", article_url, summary, doing, with_designer, props, appearance, tag, cta, is_active, i18n) values
  ('ceo', 'Chief Executive Officer', 'role', 'business', null, 'Người chịu trách nhiệm cao nhất về tầm nhìn và kết quả kinh doanh của công ty.', 'Đang xem lại OKR quý này với ban lãnh đạo.', 'Ít làm việc trực tiếp với designer, nhưng mục tiêu công ty do CEO đặt ra quyết định bạn thiết kế cho điều gì.', '["briefcase"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "The person ultimately responsible for the company''s vision and business results.", "doing": "Reviewing this quarter''s OKRs with the leadership team.", "with_designer": "Rarely works with designers directly, but the company goals the CEO sets decide what you design for."}}'::jsonb),
  ('cpo', 'Chief Product Officer', 'role', 'product', null, 'Chịu trách nhiệm chiến lược sản phẩm và quản lý đội ngũ Product Manager.', 'Đang chốt roadmap cho hai quý tới.', 'Duyệt các hướng sản phẩm lớn. Bạn sẽ trình bày với CPO ở các buổi review chiến lược.', '["flag"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Owns product strategy and manages the team of Product Managers.", "doing": "Finalising the roadmap for the next two quarters.", "with_designer": "Approves big product directions. You will present to the CPO at strategy reviews."}}'::jsonb),
  ('cto', 'Chief Technology Officer', 'role', 'engineering', null, 'Chịu trách nhiệm công nghệ, kiến trúc hệ thống và đội ngũ kỹ sư.', 'Đang rà soát chi phí hạ tầng tháng này.', 'Quyết định các giới hạn kỹ thuật, ảnh hưởng tới những gì designer có thể đề xuất.', '["laptop"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Owns technology, system architecture and the engineering team.", "doing": "Reviewing this month''s infrastructure costs.", "with_designer": "Sets the technical constraints, which shape what designers can propose."}}'::jsonb),
  ('head-of-design', 'Head of Design', 'role', 'design', null, 'Lãnh đạo toàn bộ chapter Design: tuyển dụng, chất lượng thiết kế và lộ trình phát triển của designer.', 'Đang xây khung năng lực cho các cấp designer.', 'Quản lý chuyên môn cao nhất của bạn (solid line). Bạn gặp ở các buổi all-hands của Design.', '["glasses", "pointer"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Leads the whole Design chapter: hiring, design quality and career paths for designers.", "doing": "Building a competency framework for every designer level.", "with_designer": "Your most senior craft manager (solid line). You meet at Design all-hands."}}'::jsonb),
  ('head-of-data', 'Head of Data', 'role', 'data', null, 'Lãnh đạo đội Data & Analytics và chuẩn hoá cách công ty đo lường.', 'Đang chuẩn hoá bộ chỉ số North Star.', 'Cung cấp số liệu để đánh giá một thiết kế có hiệu quả hay không.', '["chart"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Leads the Data & Analytics team and standardises how the company measures things.", "doing": "Standardising the North Star metrics.", "with_designer": "Provides the numbers that tell you whether a design actually works."}}'::jsonb),
  ('head-of-eng', 'Head of Engineering', 'role', 'engineering', null, 'Quản lý các Engineering Manager, QA Lead và chất lượng kỹ thuật chung.', 'Đang sắp xếp nhân sự cho squad mới.', 'Ít làm trực tiếp, nhưng quyết định tốc độ và cách các dev làm việc với bạn.', '["headset"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Manages the Engineering Managers, the QA Lead and overall engineering quality.", "doing": "Staffing a new squad.", "with_designer": "Rarely works with you directly, but decides how fast developers move and how they work with you."}}'::jsonb),
  ('product-manager', 'Product Manager', 'role', 'product', 'https://academy.telos.vn/product-manager-pm-la-gi-product-team/', 'Người chịu trách nhiệm về định hướng và kết quả sản phẩm: cần làm gì, tại sao, và theo thứ tự nào.', 'Đang viết user story cho luồng onboarding.', 'Đặt ưu tiên công việc cho bạn mỗi sprint (dotted line). Là người bạn trao đổi nhiều nhất mỗi ngày.', '["clipboard"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Owns the direction and outcomes of the product: what to build, why, and in what order.", "doing": "Writing user stories for the onboarding flow.", "with_designer": "Sets your priorities every sprint (dotted line). The person you talk to most every day."}}'::jsonb),
  ('product-owner', 'Product Owner', 'role', 'product', 'https://academy.telos.vn/product-owner-po-la-gi/', 'Vai trò Scrum quản lý product backlog và quyết định ưu tiên cho từng sprint.', 'Đang sắp xếp backlog cho sprint sau.', 'Làm rõ tiêu chí chấp nhận (acceptance criteria) cho từng thiết kế của bạn.', '["cards"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "The Scrum role that manages the product backlog and decides the priorities for each sprint.", "doing": "Ordering the backlog for next sprint.", "with_designer": "Clarifies the acceptance criteria for each of your designs."}}'::jsonb),
  ('growth-pm', 'Growth Product Manager', 'role', 'product', null, 'PM tập trung vào chỉ số tăng trưởng: kích hoạt, giữ chân, giới thiệu.', 'Đang đọc kết quả A/B test màn hình đăng ký.', 'Cùng bạn thiết kế thí nghiệm và đọc kết quả A/B test.', '["chart"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "A PM focused on growth metrics: activation, retention, referral.", "doing": "Reading the A/B test results for the sign-up screen.", "with_designer": "Designs experiments with you and reads the A/B test results together."}}'::jsonb),
  ('data-pm', 'Data Product Manager', 'role', 'product', null, 'PM cho các sản phẩm dữ liệu nội bộ như dashboard và hệ thống tracking.', 'Đang định nghĩa event tracking cho tính năng mới.', 'Giúp bạn gắn tracking đúng để đo hiệu quả thiết kế.', '["clipboard"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "A PM for internal data products such as dashboards and tracking systems.", "doing": "Defining event tracking for a new feature.", "with_designer": "Helps you set up the right tracking to measure how well a design performs."}}'::jsonb),
  ('ui-ux-designer', 'UI/UX Designer', 'player', 'design', 'https://academy.telos.vn/cong-viec-cua-ui-ux-designer/', 'Vai trò thiết kế giao diện và trải nghiệm người dùng: kết hợp tư duy UX và kỹ năng UI.', 'Đây là bạn. Bạn đang thiết kế luồng onboarding mới.', 'Ngồi trong squad, nhận ưu tiên từ PM, báo cáo chuyên môn cho Design Manager.', '["cap", "tablet"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Designs interfaces and user experiences, combining UX thinking with UI skills.", "doing": "This is you. You are designing a new onboarding flow.", "with_designer": "Sits in the squad, gets priorities from the PM, reports on craft to the Design Manager."}}'::jsonb),
  ('product-designer', 'Product Designer', 'role', 'design', 'https://academy.telos.vn/product-designer-la-gi-va-3-tu-duy/', 'Vai trò thiết kế toàn diện, từ research, UX đến UI, gắn liền với mục tiêu sản phẩm.', 'Đang vẽ user flow cho tính năng mời bạn bè.', 'Đồng nghiệp cùng chapter. Hai bạn hay gặp nhau ở buổi Design Critique.', '["tablet"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "An end-to-end design role, from research and UX to UI, tied closely to product goals.", "doing": "Drawing the user flow for the invite-a-friend feature.", "with_designer": "A colleague in the same chapter. You two often meet at Design Critique."}}'::jsonb),
  ('ui-designer', 'UI Designer', 'role', 'design', null, 'Tập trung vào giao diện: bố cục, màu sắc, chữ và component.', 'Đang hoàn thiện màn hình hồ sơ theo Design System.', 'Cùng chapter. Hay trao đổi với bạn về cách dùng component cho đúng.', '["palette"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Focuses on the interface: layout, colour, type and components.", "doing": "Polishing the profile screen to match the Design System.", "with_designer": "Same chapter. Often talks with you about using components the right way."}}'::jsonb),
  ('ux-designer', 'UX Designer', 'role', 'design', null, 'Tập trung vào trải nghiệm: luồng, cấu trúc thông tin và tương tác.', 'Đang vẽ lại luồng thanh toán còn 3 bước.', 'Cùng chapter. Hay cùng bạn review user flow trước khi lên UI.', '["pencil"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Focuses on the experience: flows, information architecture and interaction.", "doing": "Redrawing the checkout flow down to 3 steps.", "with_designer": "Same chapter. Often reviews user flows with you before moving to UI."}}'::jsonb),
  ('intern', 'Intern UI/UX', 'role', 'design', 'https://academy.telos.vn/intern-ui-ux-nhung-cam-nang-khi-di-thuc-tap/', 'Thực tập sinh UI/UX, học bằng cách làm cùng designer chính.', 'Đang tập vẽ wireframe theo hướng dẫn của bạn.', 'Bạn là người hướng dẫn trực tiếp. Intern hỏi bạn mọi thứ, từ file Figma đến cách họp.', '["backpack"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "A UI/UX intern who learns by working alongside a lead designer.", "doing": "Practising wireframes with your guidance.", "with_designer": "You are their direct mentor. The intern asks you everything, from Figma files to how meetings work."}}'::jsonb),
  ('ds-designer', 'Design System Designer', 'role', 'design', 'https://academy.telos.vn/design-system-designer-la-ai-product-design/', 'Xây và duy trì Design System: component library, token và guideline cho toàn sản phẩm.', 'Đang thêm biến thể mới cho component Button.', 'Hỏi họ trước khi vẽ một component mới. Có thể nó đã tồn tại.', '["palette"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Builds and maintains the Design System: the component library, tokens and guidelines for the whole product.", "doing": "Adding new variants to the Button component.", "with_designer": "Ask them before drawing a new component. It may already exist."}}'::jsonb),
  ('ux-design-engineer', 'UX Design Engineer', 'role', 'design', 'https://academy.telos.vn/ux-design-engineer-la-gi/', 'Kết hợp tư duy UX, thiết kế và code để tự triển khai trải nghiệm chất lượng cao.', 'Đang chuyển token màu từ Figma sang CSS.', 'Cầu nối giữa file Figma của bạn và code thật.', '["laptop"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Combines UX thinking, design and code to ship high-quality experiences themselves.", "doing": "Moving colour tokens from Figma into CSS.", "with_designer": "The bridge between your Figma file and real code."}}'::jsonb),
  ('design-manager', 'Design Manager', 'role', 'design', null, 'Quản lý trực tiếp các designer: review chất lượng, 1-on-1, phát triển nghề.', 'Đang chuẩn bị buổi Design Critique chiều nay.', 'Quản lý chuyên môn trực tiếp của bạn (solid line). Gặp 1-on-1 hai tuần một lần.', '["glasses", "pointer"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Directly manages designers: quality reviews, 1-on-1s, career growth.", "doing": "Preparing this afternoon''s Design Critique.", "with_designer": "Your direct craft manager (solid line). You have a 1-on-1 every two weeks."}}'::jsonb),
  ('ux-researcher', 'UX Researcher', 'role', 'design', null, 'Lên kế hoạch và thực hiện nghiên cứu người dùng.', 'Đang viết kịch bản cho buổi Usability Test.', 'Giúp bạn kiểm chứng thiết kế với người dùng thật trước khi build.', '["monocle", "clipboard"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Plans and runs user research.", "doing": "Writing the script for a Usability Test.", "with_designer": "Helps you validate designs with real users before anything gets built."}}'::jsonb),
  ('ux-writer', 'UX Writer & Content Designer', 'role', 'design', null, 'Viết chữ trong giao diện: nút, thông báo, hướng dẫn, trạng thái lỗi.', 'Đang viết lại thông báo lỗi đăng nhập.', 'Cùng bạn hoàn thiện câu chữ trên từng màn hình.', '["pencil"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Writes the words in the interface: buttons, messages, instructions, error states.", "doing": "Rewriting the login error messages.", "with_designer": "Polishes the copy on every screen with you."}}'::jsonb),
  ('motion-designer', 'Motion Designer', 'role', 'design', 'https://academy.telos.vn/motion-designer-la-ai-product-design/', 'Tạo chuyển động và animation trong sản phẩm, từ micro-interaction đến transition.', 'Đang làm animation chuyển cảnh cho onboarding.', 'Biến các tương tác bạn thiết kế thành chuyển động mượt.', '["play"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Creates motion and animation in the product, from micro-interactions to transitions.", "doing": "Animating the onboarding transitions.", "with_designer": "Turns the interactions you design into smooth motion."}}'::jsonb),
  ('tech-lead', 'Tech Lead', 'role', 'engineering', null, 'Kỹ sư dẫn dắt kỹ thuật trong squad, chịu trách nhiệm giải pháp và chất lượng code.', 'Đang ước lượng effort cho story mới.', 'Cùng bạn và PM tạo thành product trio. Trả lời câu hỏi: làm được không, tốn bao lâu.', '["headset"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "The engineer who leads technical work in the squad and owns the solution and code quality.", "doing": "Estimating effort for a new story.", "with_designer": "Forms the product trio with you and the PM. Answers the questions: can we build it, and how long will it take?"}}'::jsonb),
  ('frontend-developer', 'Frontend Developer', 'role', 'engineering', 'https://academy.telos.vn/frontend-developer-la-ai-product/', 'Developer phụ trách giao diện người dùng, người biến file Figma thành sản phẩm chạy trên trình duyệt.', 'Đang dựng component Card theo file Figma của bạn.', 'Nhận handoff từ bạn. Sẽ hỏi về spacing, trạng thái và responsive.', '["laptop"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "The developer who builds the user interface, turning your Figma file into a product that runs in the browser.", "doing": "Building the Card component from your Figma file.", "with_designer": "Receives your handoff. Will ask about spacing, states and responsive behaviour."}}'::jsonb),
  ('backend-developer', 'Backend Developer', 'role', 'engineering', 'https://academy.telos.vn/backend-developer-la-ai-product/', 'Developer phụ trách logic, dữ liệu và API phía server.', 'Đang viết API lưu tiến độ onboarding.', 'Cho bạn biết dữ liệu nào có sẵn và hệ thống phản hồi nhanh tới đâu.', '["database"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "The developer behind server-side logic, data and APIs.", "doing": "Writing the API that saves onboarding progress.", "with_designer": "Tells you what data is available and how fast the system can respond."}}'::jsonb),
  ('fullstack-developer', 'Full-stack Developer', 'role', 'engineering', 'https://academy.telos.vn/full-stack-developer-la-ai-product/', 'Developer làm cả Frontend lẫn Backend, linh hoạt cho team cần tốc độ.', 'Đang làm landing page SEO từ đầu đến cuối.', 'Hay cùng bạn thử nhanh một ý tưởng trong vài ngày.', '["laptop"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "A developer who works on both frontend and backend, flexible for teams that need speed.", "doing": "Building an SEO landing page end to end.", "with_designer": "Often tries out an idea with you in just a few days."}}'::jsonb),
  ('mobile-developer', 'Mobile Developer', 'role', 'engineering', null, 'Developer làm ứng dụng iOS và Android.', 'Đang sửa lỗi cử chỉ vuốt trên Android.', 'Hỏi bạn về khác biệt pattern giữa iOS và Android.', '["phone"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "A developer building iOS and Android apps.", "doing": "Fixing a swipe gesture bug on Android.", "with_designer": "Asks you about pattern differences between iOS and Android."}}'::jsonb),
  ('qa-engineer', 'QA Engineer', 'role', 'engineering', null, 'Kỹ sư kiểm thử, đảm bảo sản phẩm chạy đúng trước khi ra mắt.', 'Đang viết test case cho luồng thanh toán.', 'So bản build với thiết kế của bạn và báo lại khi có chỗ lệch.', '["magnifier"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "A test engineer who makes sure the product works correctly before release.", "doing": "Writing test cases for the checkout flow.", "with_designer": "Compares the build against your design and flags anything that does not match."}}'::jsonb),
  ('software-architect', 'Software Architect', 'role', 'engineering', null, 'Người thiết kế kiến trúc tổng thể của hệ thống.', 'Đang vẽ sơ đồ tách dịch vụ thanh toán.', 'Ít làm trực tiếp, nhưng quyết định của họ ảnh hưởng tốc độ và giới hạn tính năng.', '["scroll"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Designs the overall architecture of the system.", "doing": "Diagramming how to split out the payment service.", "with_designer": "Rarely works with you directly, but their decisions affect speed and feature limits."}}'::jsonb),
  ('devops', 'DevOps & Platform Engineer', 'role', 'engineering', null, 'Xây hạ tầng và pipeline deploy, giữ hệ thống chạy ổn định.', 'Đang theo dõi bản deploy chiều nay.', 'Khi sản phẩm chậm hay sập, họ là người xử lý đầu tiên.', '["gear"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Builds the infrastructure and deploy pipelines, and keeps the system running.", "doing": "Watching this afternoon''s deploy.", "with_designer": "When the product is slow or goes down, they are the first to respond."}}'::jsonb),
  ('data-analyst', 'Data Analyst', 'role', 'data', null, 'Phân tích dữ liệu để trả lời câu hỏi về sản phẩm và kinh doanh.', 'Đang dựng funnel đăng ký của tuần này.', 'Cho bạn biết người dùng rời đi ở bước nào của luồng.', '["chart"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Analyses data to answer questions about the product and the business.", "doing": "Building this week''s sign-up funnel.", "with_designer": "Shows you at which step of a flow users drop off."}}'::jsonb),
  ('bi-analyst', 'Business Intelligence Analyst', 'role', 'data', null, 'Xây dashboard và báo cáo định kỳ cho các phòng ban.', 'Đang cập nhật dashboard doanh thu.', 'Dashboard của họ là nơi bạn tìm số liệu nhanh nhất.', '["pie"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Builds dashboards and recurring reports for every department.", "doing": "Updating the revenue dashboard.", "with_designer": "Their dashboards are the fastest place to find numbers."}}'::jsonb),
  ('data-scientist', 'Data Scientist', 'role', 'data', null, 'Xây mô hình dự đoán và gợi ý từ dữ liệu.', 'Đang huấn luyện mô hình gợi ý khoá học.', 'Cùng bạn thiết kế cách hiển thị gợi ý do AI tạo ra.', '["flask"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Builds prediction and recommendation models from data.", "doing": "Training the course recommendation model.", "with_designer": "Designs with you how AI-generated recommendations are shown."}}'::jsonb),
  ('data-engineer', 'Data Engineer', 'role', 'data', null, 'Xây đường ống dữ liệu để các nhóm khác dùng được dữ liệu.', 'Đang sửa pipeline đồng bộ dữ liệu đêm qua.', 'Ít làm trực tiếp, nhưng tracking bạn đề xuất cần họ để chạy.', '["database"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Builds the data pipelines that let other teams use data.", "doing": "Fixing last night''s data sync pipeline.", "with_designer": "Rarely works with you directly, but the tracking you propose needs them to run."}}'::jsonb),
  ('scrum-master', 'Scrum Master', 'role', 'delivery', null, 'Giữ nhịp Scrum: điều phối các buổi họp và gỡ vướng mắc cho team.', 'Đang chuẩn bị buổi Retro cuối sprint.', 'Giúp bạn gỡ những việc đang bị chặn trong sprint.', '["timer"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Keeps the Scrum rhythm: runs the ceremonies and clears blockers for the team.", "doing": "Preparing the end-of-sprint Retro.", "with_designer": "Helps you unblock work that is stuck in the sprint."}}'::jsonb),
  ('delivery-manager', 'Delivery Manager', 'role', 'delivery', null, 'Đảm bảo các team giao sản phẩm đúng hạn và phối hợp tốt với nhau.', 'Đang cập nhật kế hoạch phát hành.', 'Cho bạn biết hạn chót thật sự của một tính năng.', '["calendar"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Makes sure teams ship on time and coordinate well with each other.", "doing": "Updating the release plan.", "with_designer": "Tells you the real deadline for a feature."}}'::jsonb),
  ('project-manager', 'Project Manager', 'role', 'delivery', null, 'Quản lý dự án theo phạm vi, thời gian và nguồn lực.', 'Đang theo dõi tiến độ dự án tích hợp đối tác.', 'Cần bạn ước lượng thời gian thiết kế cho từng hạng mục.', '["calendar"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Manages projects by scope, time and resources.", "doing": "Tracking progress on the partner integration project.", "with_designer": "Needs you to estimate design time for each work item."}}'::jsonb),
  ('growth-manager', 'Growth Manager', 'role', 'business', null, 'Phụ trách tăng trưởng người dùng qua nhiều kênh marketing.', 'Đang lên chiến dịch giới thiệu bạn bè.', 'Cần bạn thiết kế landing page và luồng mời bạn bè.', '["megaphone"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Drives user growth across many marketing channels.", "doing": "Planning a refer-a-friend campaign.", "with_designer": "Needs you to design landing pages and the invite-a-friend flow."}}'::jsonb),
  ('performance-marketer', 'Performance Marketing Manager', 'role', 'business', null, 'Chạy quảng cáo trả phí và tối ưu chi phí trên mỗi người dùng.', 'Đang so sánh 3 mẫu banner quảng cáo.', 'Hay nhờ bạn làm biến thể banner và trang đích.', '["megaphone"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Runs paid ads and optimises the cost per user.", "doing": "Comparing 3 ad banner variants.", "with_designer": "Often asks you for banner variants and landing pages."}}'::jsonb),
  ('brand-manager', 'Brand Manager', 'role', 'business', null, 'Giữ gìn hình ảnh và giọng nói của thương hiệu.', 'Đang duyệt bộ nhận diện cho chiến dịch mới.', 'Bạn cần tuân theo guideline thương hiệu họ đặt ra.', '["flag"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Protects the brand''s image and voice.", "doing": "Approving the identity kit for a new campaign.", "with_designer": "You need to follow the brand guidelines they set."}}'::jsonb),
  ('content-marketer', 'Content Marketer', 'role', 'business', null, 'Viết nội dung cho blog, mạng xã hội và email.', 'Đang viết bài blog ra mắt tính năng.', 'Cần ảnh minh hoạ tính năng từ bạn.', '["pencil"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Writes content for the blog, social media and email.", "doing": "Writing the launch blog post for a feature.", "with_designer": "Needs feature illustrations from you."}}'::jsonb),
  ('crm-manager', 'CRM Manager', 'role', 'business', null, 'Quản lý email, thông báo và chương trình giữ chân khách hàng.', 'Đang thiết lập chuỗi email chào mừng.', 'Cùng bạn thiết kế email và thông báo trong app.', '["cards"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Manages email, notifications and customer retention programmes.", "doing": "Setting up the welcome email sequence.", "with_designer": "Designs emails and in-app messages with you."}}'::jsonb),
  ('seo-specialist', 'SEO Specialist', 'role', 'business', null, 'Tối ưu website để xuất hiện tốt trên Google.', 'Đang kiểm tra tốc độ tải trang.', 'Góp ý cấu trúc trang và tiêu đề khi bạn làm landing page.', '["magnifier"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Optimises the website to rank well on Google.", "doing": "Checking page load speed.", "with_designer": "Gives feedback on page structure and headings when you build landing pages."}}'::jsonb),
  ('csm', 'Customer Success Manager', 'role', 'business', null, 'Giúp khách hàng dùng sản phẩm thành công và gia hạn.', 'Đang gọi cho khách hàng sắp hết hạn.', 'Mang về phản hồi thật từ khách hàng cho bạn.', '["headset"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Helps customers succeed with the product and renew.", "doing": "Calling customers whose plans are about to expire.", "with_designer": "Brings real customer feedback back to you."}}'::jsonb),
  ('customer-support', 'Customer Support', 'role', 'business', null, 'Trả lời câu hỏi và xử lý sự cố của khách hàng.', 'Đang trả lời 12 ticket về quên mật khẩu.', 'Nguồn insight quý: lỗi nào người dùng hỏi nhiều nhất.', '["headset"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Answers customer questions and handles their problems.", "doing": "Answering 12 tickets about forgotten passwords.", "with_designer": "A valuable source of insight: which problems users ask about most."}}'::jsonb),
  ('account-manager', 'Account Manager', 'role', 'business', null, 'Quản lý quan hệ và hợp đồng với khách hàng lớn.', 'Đang chuẩn bị buổi demo cho khách hàng doanh nghiệp.', 'Cần bạn làm bản demo đẹp cho khách hàng lớn.', '["briefcase"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Manages relationships and contracts with large customers.", "doing": "Preparing a demo for an enterprise customer.", "with_designer": "Needs you to make a polished demo for big customers."}}'::jsonb),
  ('business-analyst', 'Business Analyst', 'role', 'business', 'https://academy.telos.vn/business-analyst-ba-la-gi-product-team/', 'Phân tích yêu cầu kinh doanh và dịch chúng thành đặc tả cho design và engineering.', 'Đang viết đặc tả yêu cầu cho tính năng hoá đơn.', 'Dịch yêu cầu kinh doanh thành đặc tả để bạn thiết kế.', '["clipboard"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Analyses business requirements and translates them into specifications for design and engineering.", "doing": "Writing the requirements spec for the invoicing feature.", "with_designer": "Translates business requirements into specs for you to design from."}}'::jsonb),
  ('stakeholder', 'Stakeholder', 'role', 'business', 'https://academy.telos.vn/stakeholder-la-ai-product/', 'Những người có lợi ích liên quan tới sản phẩm, có thể ảnh hưởng hoặc bị ảnh hưởng bởi quyết định thiết kế.', 'Đang chờ buổi Sprint Review để xem demo.', 'Bạn cần thuyết phục họ bằng lý do, dữ liệu và bản demo rõ ràng.', '["briefcase"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "People with a stake in the product, who can influence or be affected by design decisions.", "doing": "Waiting for the Sprint Review to see the demo.", "with_designer": "You need to convince them with reasons, data and a clear demo."}}'::jsonb),
  ('nhan-luu', 'Nhân Lưu', 'author', 'design', null, 'Cha nội này là Academic Director tại TELOS Academy và là tác giả của trò chơi này. Ổng đi khắp các phòng để kể chuyện cười không vui làm giảm năng suất làm việc của mọi người.', 'Đang đi một vòng văn phòng, hỏi thăm từng team.', 'Ổng có thể chỉ cho bạn lộ trình học UI/UX và hướng phát triển trong lĩnh vực này.', '["blazer", "glasses", "necklace", "laptopCarry"]'::jsonb, '{"dark": false, "outfit": {"legs": "#C9BA95", "feet": "#B48D5C"}}'::jsonb, 'Academic Director · TELOS Academy', '[{"label": "Nhận quà", "url": "https://nhanluu.com/contact/", "primary": true}, {"label": "Tìm hiểu thêm", "url": "https://nhanluu.com"}]'::jsonb, true, '{"en": {"summary": "This guy is the Academic Director at TELOS Academy and the author of this game. He wanders from room to room telling unfunny jokes that lower everyone''s productivity.", "doing": "Walking around the office, checking in on every team.", "with_designer": "He can show you a learning path for UI/UX and where to grow in this field.", "tag": "Academic Director · TELOS Academy", "cta": ["Get a gift", "Learn more"]}}'::jsonb),
  ('user', 'User', 'guest', 'business', null, 'Người dùng thật của sản phẩm. Bạn ấy không quan tâm team làm việc ra sao, chỉ quan tâm sản phẩm có dễ dùng hay không.', 'Đang ngồi bấm điện thoại, lướt thử ứng dụng.', 'Hỏi và quan sát người dùng thật là cách nhanh nhất để biết thiết kế của bạn có dùng được không.', '["phoneUse"]'::jsonb, '{"dark": true, "outfit": null}'::jsonb, 'Người dùng thật', '[{"label": "Usability Testing", "url": "https://academy.telos.vn/usability-testing-la-gi-ux-design/", "primary": true}, {"label": "Learnability", "url": "https://academy.telos.vn/learnability-la-gi-ux-design/", "primary": false}]'::jsonb, true, '{"en": {"summary": "A real user of the product. They don''t care how the team works, only whether the product is easy to use.", "doing": "Tapping away on their phone, trying out the app.", "with_designer": "Asking and watching real users is the fastest way to know whether your design actually works.", "tag": "Real user", "cta": ["Usability Testing", "Learnability"]}}'::jsonb),
  ('client', 'Client', 'role', 'business', null, 'Khách hàng thuê agency làm sản phẩm. Họ trả tiền, đặt mục tiêu và là người quyết định cuối cùng, nhưng họ không phải người dùng của sản phẩm.', 'Đang ngồi chờ buổi họp, tranh thủ trả lời tin nhắn công việc.', 'Bạn trình bày thiết kế cho họ và nghe phản hồi. Mọi yêu cầu mới của họ phải đi qua Account Manager và Project Manager.', '["briefcase"]'::jsonb, '{"dark": false, "outfit": null, "body_color": "#FFC53D", "outline_color": "#8A5D00"}'::jsonb, 'Khách hàng của agency', null, true, '{"en": {"summary": "The customer who hires the agency to build their product. They pay, set the goals and have the final say, but they are not the product''s users.", "doing": "Waiting for the meeting while answering work messages.", "with_designer": "You present designs to them and listen to their feedback. Every new request from them must go through the Account Manager and the Project Manager.", "tag": "The agency''s client"}}'::jsonb),
  ('design-director', 'Design Director', 'role', 'design', null, 'Người chịu trách nhiệm về chất lượng thiết kế của cả agency. Mọi bản thiết kế phải qua Design Director trước khi gửi khách.', 'Đang xem lại concept của ba dự án khác nhau.', 'Quản lý chuyên môn trực tiếp của bạn. Duyệt thiết kế, góp ý và quyết định bản nào đủ tốt để gửi khách.', '["glasses", "pointer"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Responsible for the design quality of the whole agency. Every design has to pass the Design Director before it goes to a client.", "doing": "Reviewing concepts for three different projects.", "with_designer": "Your direct craft manager. Approves designs, gives feedback and decides which version is good enough to send to the client."}}'::jsonb),
  ('graphic-designer', 'Graphic Designer', 'role', 'design', null, 'Designer làm nhận diện thương hiệu, banner, hình minh hoạ và ấn phẩm truyền thông.', 'Đang chỉnh bộ banner cho chiến dịch khai trương của khách.', 'Cho bạn biết màu, font và hình ảnh thương hiệu của khách để giao diện không lệch nhận diện.', '["palette"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "A designer who works on brand identity, banners, illustrations and marketing materials.", "doing": "Adjusting the banner set for a client''s grand opening campaign.", "with_designer": "Tells you the client''s brand colours, fonts and imagery so the interface stays on brand."}}'::jsonb),
  ('sales', 'Sales / Business Developer', 'role', 'business', null, 'Người đi tìm khách hàng và mang dự án về cho agency.', 'Đang chuẩn bị slide cho buổi gặp khách chiều nay.', 'Hay nhờ bạn dựng nhanh một bản demo để khách dễ hình dung trước khi ký hợp đồng.', '["megaphone"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "Finds clients and brings projects into the agency.", "doing": "Preparing slides for this afternoon''s client meeting.", "with_designer": "Often asks you to put together a quick demo so the client can picture the product before signing."}}'::jsonb),
  ('freelancer', 'Freelancer', 'role', 'design', 'https://academy.telos.vn/cach-lam-freelance-thiet-ke-giao-dien/', 'Designer làm việc độc lập, được agency thuê theo từng dự án khi team thiếu người.', 'Đang làm bộ icon cho một dự án cần gấp trong tuần này.', 'Làm cùng bạn trong vài tuần rồi rời đi. Bạn cần bàn giao file gọn gàng để họ vào việc nhanh.', '["laptop", "backpack"]'::jsonb, '{"dark": false, "outfit": null}'::jsonb, null, null, true, '{"en": {"summary": "An independent designer the agency hires per project when the team is short on people.", "doing": "Making an icon set for a project that is due this week.", "with_designer": "Works with you for a few weeks and then leaves. Hand over clean files so they can get going fast."}}'::jsonb)
