insert into tm_quests (id, type, scale, sort_order, title, room_id, giver, gather, offer_text, done_text, rewards, is_active, daily_date, i18n) values
  ('small-01', 'main', 'small', 1, 'Nhận việc đầu sprint', 'P4', 'product-manager@P1', '["tech-lead@P2", "frontend-developer@P2"]'::jsonb, 'Chào bạn! Sprint này mình làm lại luồng onboarding. Trước khi vẽ, bạn hỏi Tech Lead xem phần nào khó làm nhé.', 'Tuyệt, wireframe rõ ràng. Bước ảnh đại diện để sprint sau.', '[{"type": "character", "id": "product-manager"}, {"type": "term", "name": "Agile", "url": "https://academy.telos.vn/waterfall-va-agile-la-gi/"}]'::jsonb, true, null, '{"en": {"title": "Picking up work at sprint start", "offer_text": "Hi! This sprint we''re redoing the onboarding flow. Before you start drawing, ask the Tech Lead which parts are hard to build.", "done_text": "Great, the wireframe is clear. We''ll leave the profile photo step for next sprint."}}'::jsonb),
  ('small-02', 'main', 'small', 2, 'Hiểu mục tiêu kinh doanh', 'P3', 'ceo@P3', '["business-analyst@P3"]'::jsonb, 'Quý này công ty cần tăng 20% người dùng trả phí. Bạn hỏi BA xem onboarding liên quan thế nào.', 'Đúng rồi. Thiết kế nào giúp người dùng thấy giá trị sớm là thiết kế tốt.', '[{"type": "character", "id": "business-analyst"}, {"type": "term", "name": "Viability", "url": "https://academy.telos.vn/viability-la-gi-product-design/"}]'::jsonb, true, null, '{"en": {"title": "Understanding the business goal", "offer_text": "This quarter the company needs 20% more paying users. Ask the BA how onboarding ties into that.", "done_text": "Exactly. A design that helps users see value early is a good design."}}'::jsonb),
  ('small-03', 'main', 'small', 3, 'Nghe tiếng nói khách hàng', 'P3', 'customer-support@P3', '["account-manager@P3"]'::jsonb, 'Mình nhận rất nhiều câu hỏi về bước đăng ký. Bạn sang hỏi Account Manager thêm góc nhìn khách lớn nhé.', 'Bạn ghi lại hai insight này vào persona nhé. Cảm ơn bạn đã lắng nghe!', '[{"type": "term", "name": "User Persona", "url": "https://academy.telos.vn/user-persona-la-gi-cach-tao-ra-1-user-persona/"}, {"type": "term", "name": "Empathy Map", "url": "https://academy.telos.vn/huong-dan-nguoi-moi-ve-empathy-map-la-gi/"}]'::jsonb, true, null, '{"en": {"title": "Listening to customers", "offer_text": "We get a lot of questions about the sign-up step. Go ask the Account Manager for the big customers'' point of view too.", "done_text": "Add these two insights to the persona. Thanks for listening!"}}'::jsonb),
  ('small-04', 'main', 'small', 4, 'Handoff cho Dev team', 'P2', 'frontend-developer@P2', '["qa-engineer@P2", "mobile-developer@P2"]'::jsonb, 'File Figma xong rồi hả? Trước khi code, bạn giải thích các trạng thái lỗi cho QA giúp mình.', 'Cảm ơn bạn. Có prototype bấm thử được nên mình hiểu luồng nhanh hơn nhiều.', '[{"type": "character", "id": "frontend-developer"}, {"type": "term", "name": "Prototype", "url": "https://academy.telos.vn/prototype-la-gi-video-huong-dan/"}]'::jsonb, true, null, '{"en": {"title": "Handoff to the Dev team", "offer_text": "Is the Figma file done? Before we code, please walk QA through the error states.", "done_text": "Thank you. With a clickable prototype I understood the flow much faster."}}'::jsonb),
  ('small-05', 'main', 'small', 5, 'Demo cuối sprint', 'P4', 'product-manager@P1', '["ceo@P3", "growth-manager@P3", "tech-lead@P2", "customer-support@P3"]'::jsonb, 'Đến giờ demo rồi! Cả công ty đang ở phòng họp. Bạn trình bày rồi hỏi ý kiến CEO nhé.', 'Sprint đầu tiên của bạn hoàn thành rồi. Chào mừng tới team!', '[{"type": "character", "id": "stakeholder"}, {"type": "term", "name": "Desirability", "url": "https://academy.telos.vn/desirability-la-gi/"}]'::jsonb, true, null, '{"en": {"title": "End-of-sprint demo", "offer_text": "Demo time! The whole company is in the meeting room. Present your work, then ask the CEO for feedback.", "done_text": "Your first sprint is done. Welcome to the team!"}}'::jsonb),
  ('large-01', 'main', 'large', 1, 'Sprint Planning', 'R08', 'product-manager@R03', '["tech-lead@R03", "frontend-developer@R03", "qa-engineer@R03"]'::jsonb, 'Sprint này squad Core làm lại luồng onboarding. Bạn hỏi Tech Lead ước lượng effort cho phần thiết kế mới nhé.', 'Ok, mình chốt story này vào sprint. Nhớ ghé team Design System nhé.', '[{"type": "character", "id": "product-manager"}, {"type": "term", "name": "Agile", "url": "https://academy.telos.vn/waterfall-va-agile-la-gi/"}]'::jsonb, true, null, '{"en": {"title": "Sprint Planning", "offer_text": "This sprint the Core squad is redoing the onboarding flow. Ask the Tech Lead to estimate the effort for the new design.", "done_text": "OK, I''m putting this story into the sprint. Remember to drop by the Design System team."}}'::jsonb),
  ('large-02', 'main', 'large', 2, 'Discovery cùng số liệu', 'R03', 'tech-lead@R03', '["product-manager@R03"]'::jsonb, 'Trước khi vẽ, mình cần biết người dùng rơi ở bước nào. Bạn sang Data & Analytics xin số liệu funnel nhé.', '42% là con số lớn. Vấn đề rõ rồi, giờ mới tới giải pháp.', '[{"type": "term", "name": "Problem Statement", "url": "https://academy.telos.vn/problem-statement-cach-xac-dinh-cho-nguoi-moi-hoc-ui-ux/"}, {"type": "term", "name": "Customer Journey Map", "url": "https://academy.telos.vn/customer-journey-map-hanh-trinh-khach-hang/"}]'::jsonb, true, null, '{"en": {"title": "Discovery with data", "offer_text": "Before drawing, we need to know where users drop off. Go to Data & Analytics and ask for the funnel numbers.", "done_text": "42% is a big number. The problem is clear now, only then do we move to solutions."}}'::jsonb),
  ('large-03', 'main', 'large', 3, 'Kiểm tra component', 'R05', 'ds-designer@R05', '["ux-design-engineer@R05"]'::jsonb, 'Bạn định vẽ thẻ chọn sở thích mới à? Hỏi UX Design Engineer xem component Chip đã có những gì đã.', 'Vậy mình thêm một biến thể thay vì làm component mới. Cảm ơn bạn đã hỏi trước!', '[{"type": "character", "id": "ds-designer"}, {"type": "term", "name": "Design System", "url": "https://academy.telos.vn/design-system-la-gi/"}]'::jsonb, true, null, '{"en": {"title": "Checking the components", "offer_text": "Planning to draw a new interest-picker card? Ask the UX Design Engineer what the Chip component already has.", "done_text": "So we add a variant instead of a new component. Thanks for asking first!"}}'::jsonb),
  ('large-04', 'main', 'large', 4, 'Design Critique', 'R06', 'design-manager@R06', '["product-designer@R02", "ui-designer@R03", "ux-designer@R04"]'::jsonb, 'Chiều nay đến lượt bạn trình bày wireframe. Lấy góp ý từ Product Designer và UX Designer nhé.', 'Hai góp ý rất tốt. Critique là để thiết kế tốt hơn, không phải để chấm điểm bạn.', '[{"type": "term", "name": "Heuristic Evaluation", "url": "https://academy.telos.vn/phuong-phap-heuristic-evaluation/"}, {"type": "term", "name": "Wireframe", "url": "https://academy.telos.vn/wireframe-khung-xuong-cua-thiet-ke/"}]'::jsonb, true, null, '{"en": {"title": "Design Critique", "offer_text": "This afternoon it''s your turn to present your wireframes. Get feedback from the Product Designer and the UX Designer.", "done_text": "Two great pieces of feedback. Critique is there to make the design better, not to grade you."}}'::jsonb),
  ('large-05', 'main', 'large', 5, 'Usability Test', 'R11', 'ux-researcher@R06', '["product-manager@R03"]'::jsonb, 'Mình mời được một người dùng thật, bạn ấy đang ngồi ở Pantry. Bạn cùng mình hỏi bạn ấy thử luồng onboarding nhé.', 'Một vấn đề thật, từ người dùng thật. Bạn sửa độ tương phản nút đó trước khi handoff nhé.', '[{"type": "term", "name": "Usability Testing", "url": "https://academy.telos.vn/usability-testing-la-gi-ux-design/"}, {"type": "term", "name": "Usability", "url": "https://academy.telos.vn/usability-la-gi-ux-design/"}]'::jsonb, true, null, '{"en": {"title": "Usability Test", "offer_text": "I''ve invited a real user, they''re sitting in the Pantry. Let''s ask them to try the onboarding flow together.", "done_text": "A real problem, from a real user. Fix that button''s contrast before handoff."}}'::jsonb),
  ('large-06', 'main', 'large', 6, 'Handoff', 'R03', 'frontend-developer@R03', '["qa-engineer@R03", "mobile-developer@R03"]'::jsonb, 'File xong chưa? Bạn giải thích trạng thái lỗi và trạng thái tải cho QA giúp mình.', 'Có prototype bấm thử nên cả team hiểu luồng rất nhanh. Cảm ơn bạn!', '[{"type": "character", "id": "frontend-developer"}, {"type": "term", "name": "Prototype", "url": "https://academy.telos.vn/prototype-la-gi-video-huong-dan/"}]'::jsonb, true, null, '{"en": {"title": "Handoff", "offer_text": "Is the file ready? Please walk QA through the error and loading states.", "done_text": "With a clickable prototype the whole team got the flow really fast. Thank you!"}}'::jsonb),
  ('large-07', 'main', 'large', 7, 'Sprint Review', 'R08', 'product-manager@R03', '["growth-manager@R10", "csm@R10", "stakeholder@R08", "tech-lead@R03"]'::jsonb, 'Đến giờ demo rồi. Marketing và Customer Success đều tới. Bạn nghe phản hồi từ hai bên nhé.', 'Hai ý này mình đưa vào backlog sprint sau. Demo của bạn rất thuyết phục.', '[{"type": "character", "id": "stakeholder"}, {"type": "term", "name": "Desirability", "url": "https://academy.telos.vn/desirability-la-gi/"}]'::jsonb, true, null, '{"en": {"title": "Sprint Review", "offer_text": "Demo time. Marketing and Customer Success are both here. Listen to feedback from both sides.", "done_text": "I''ll put both ideas into next sprint''s backlog. Your demo was very convincing."}}'::jsonb),
  ('large-08', 'main', 'large', 8, '1-on-1 cuối sprint', 'R06', 'design-manager@R06', '[]'::jsonb, 'Sprint vừa rồi bạn đã làm việc với gần như mọi phòng ban. Mình nói chuyện về mục tiêu phát triển của bạn nhé.', 'Mục tiêu quý tới: tự dẫn một buổi Critique và bắt đầu làm portfolio từ dự án này.', '[{"type": "character", "id": "product-designer"}, {"type": "term", "name": "Portfolio", "url": "https://academy.telos.vn/product-designer-portfolio-gom-gi/"}]'::jsonb, true, null, '{"en": {"title": "End-of-sprint 1-on-1", "offer_text": "This sprint you worked with almost every department. Let''s talk about your growth goals.", "done_text": "Goals for next quarter: run a Critique session yourself and start a portfolio piece from this project."}}'::jsonb),
  ('agency-01', 'main', 'agency', 1, 'Làm demo để chốt hợp đồng', 'A6', 'sales@A6', '["ceo@A6"]'::jsonb, 'Chiều nay mình đi gặp một chuỗi phòng gym, họ muốn làm app đặt lịch tập. Bạn dựng giúp mình một màn hình demo nhé. Không cần hoàn chỉnh, miễn là khách hình dung được.', 'Chốt được rồi! Khách ký hợp đồng 8 tuần. Tuần sau kickoff, bạn vào dự án này nhé.', '[{"type": "term", "name": "Mockup", "url": "https://academy.telos.vn/mockup-la-gi-huong-dan-toan-tap-cho-nguoi-moi/"}, {"type": "term", "name": "Portfolio", "url": "https://academy.telos.vn/product-designer-portfolio-gom-gi/"}]'::jsonb, true, null, '{"en": {"title": "A demo to close the deal", "offer_text": "This afternoon I''m meeting a gym chain that wants a class-booking app. Can you put together one demo screen for me? It doesn''t need to be complete, just enough for the client to picture it.", "done_text": "We closed it! The client signed an 8-week contract. Kickoff is next week and you''re on this project."}}'::jsonb),
  ('agency-02', 'main', 'agency', 2, 'Kickoff và nhận brief', 'A4', 'account-manager@A3', '["project-manager@A3"]'::jsonb, 'Hôm nay kickoff với khách. Bạn đừng vội nói về giao diện. Hãy hỏi xem họ muốn đạt điều gì và hội viên của họ là ai.', 'Hỏi hay lắm. Biết mục tiêu của khách rồi thì sau này mình có cơ sở để từ chối những yêu cầu lạc đề.', '[{"type": "character", "id": "stakeholder"}, {"type": "term", "name": "Problem Statement", "url": "https://academy.telos.vn/problem-statement-cach-xac-dinh-cho-nguoi-moi-hoc-ui-ux/"}]'::jsonb, true, null, '{"en": {"title": "Kickoff and the brief", "offer_text": "Kickoff with the client is today. Don''t jump into the interface yet. Ask what they want to achieve and who their members are.", "done_text": "Great questions. Now that we know the client''s goal, we have grounds to say no to off-topic requests later."}}'::jsonb),
  ('agency-03', 'main', 'agency', 3, 'Chốt phạm vi dự án', 'A3', 'project-manager@A3', '["business-analyst@A3"]'::jsonb, 'Hợp đồng là 8 tuần với ngân sách cố định. Bạn hỏi BA danh sách màn hình, rồi sang hỏi Tech Lead xem làm kịp không.', 'Vậy giai đoạn 1 là 9 màn hình, chưa có thanh toán. Mình ghi rõ vào biên bản để sau này không ai tranh cãi.', '[{"type": "character", "id": "business-analyst"}, {"type": "term", "name": "MVP", "url": "https://academy.telos.vn/mo-hinh-mvp-trong-hoc-ui-ux-hoc-cach-hoan-thanh/"}, {"type": "term", "name": "Feasibility", "url": "https://academy.telos.vn/feasibility-la-gi-product-design/"}]'::jsonb, true, null, '{"en": {"title": "Locking the project scope", "offer_text": "The contract is 8 weeks with a fixed budget. Ask the BA for the list of screens, then ask the Tech Lead whether we can make it in time.", "done_text": "So phase 1 is 9 screens, no payments yet. I''ll write it into the minutes so nobody argues about it later."}}'::jsonb),
  ('agency-04', 'main', 'agency', 4, 'Duyệt nội bộ', 'A1', 'design-director@A1', '["graphic-designer@A1"]'::jsonb, 'Trước khi gửi khách, mọi thứ phải qua mình. Bạn làm concept cho luồng đặt lịch rồi mang lại đây.', 'Luồng 3 bước rõ ràng. Sửa lại độ tương phản chữ trên nền cam rồi gửi khách được. Nhớ nhé: khách chỉ nên thấy bản đã duyệt nội bộ.', '[{"type": "term", "name": "Wireframe", "url": "https://academy.telos.vn/wireframe-khung-xuong-cua-thiet-ke/"}, {"type": "term", "name": "Heuristic Evaluation", "url": "https://academy.telos.vn/phuong-phap-heuristic-evaluation/"}]'::jsonb, true, null, '{"en": {"title": "Internal review", "offer_text": "Before anything goes to the client, it goes through me. Make a concept for the booking flow and bring it here.", "done_text": "A clear 3-step flow. Fix the text contrast on the orange background and it can go to the client. Remember: clients should only see work that passed internal review."}}'::jsonb),
  ('agency-05', 'main', 'agency', 5, 'Trình bày cho khách hàng', 'A4', 'account-manager@A3', '["design-director@A1", "project-manager@A3"]'::jsonb, 'Khách tới rồi. Bạn trình bày concept nhé. Nhớ bắt đầu từ mục tiêu của họ, đừng bắt đầu từ màu sắc.', 'Khách thích luồng chính là thắng lớn rồi. Mấy thứ khách đòi thêm thì đừng gật ngay, để mình và PM xem lại hợp đồng đã.', '[{"type": "term", "name": "Prototype", "url": "https://academy.telos.vn/prototype-la-gi-video-huong-dan/"}, {"type": "term", "name": "Desirability", "url": "https://academy.telos.vn/desirability-la-gi/"}]'::jsonb, true, null, '{"en": {"title": "Presenting to the client", "offer_text": "The client is here. Present your concept. Remember to start from their goals, not from the colours.", "done_text": "The client likes the main flow, that''s a big win. Don''t say yes right away to the extras they asked for, let me and the PM check the contract first."}}'::jsonb),
  ('agency-06', 'main', 'agency', 6, 'Khách hàng đổi ý', 'A4', 'client@A4', '[]'::jsonb, 'À em ơi, tiện thể làm luôn cho anh phần bán gói tập online với tích điểm đổi quà nhé. Chắc thêm vài màn hình thôi mà.', 'Ừ, anh hiểu rồi. Vậy cứ làm xong giai đoạn 1 đã, phần kia bên em báo giá sau nhé.', '[{"type": "term", "name": "Viability", "url": "https://academy.telos.vn/viability-la-gi-product-design/"}, {"type": "term", "name": "Agile", "url": "https://academy.telos.vn/waterfall-va-agile-la-gi/"}]'::jsonb, true, null, '{"en": {"title": "The client changes their mind", "offer_text": "Oh, while you''re at it, can you also add online class packages and a points-for-rewards scheme? Should only be a few more screens.", "done_text": "OK, I get it. Let''s finish phase 1 first, and your team can send me a quote for the rest later."}}'::jsonb),
  ('agency-07', 'main', 'agency', 7, 'Thuyết phục bằng người dùng', 'A3', 'project-manager@A3', '["account-manager@A3"]'::jsonb, 'Khách vẫn muốn nhồi banner lên trang chủ. Cãi bằng ý kiến cá nhân thì mình thua. Bạn ra Pantry cho một hội viên dùng thử rồi mang kết quả về.', 'Thấy chưa, khách không nghe designer nhưng nghe người dùng của họ. Lần sau cứ test trước khi tranh luận.', '[{"type": "term", "name": "Usability Testing", "url": "https://academy.telos.vn/usability-testing-la-gi-ux-design/"}, {"type": "term", "name": "User Persona", "url": "https://academy.telos.vn/user-persona-la-gi-cach-tao-ra-1-user-persona/"}]'::jsonb, true, null, '{"en": {"title": "Winning the argument with users", "offer_text": "The client still wants to stuff banners onto the home screen. If we argue with personal opinions, we lose. Go to the Pantry, have a member try it, and bring back the results.", "done_text": "See? The client doesn''t listen to designers, but they do listen to their users. Next time, test before you argue."}}'::jsonb),
  ('agency-08', 'main', 'agency', 8, 'Handoff và nghiệm thu', 'A2', 'tech-lead@A2', '["frontend-developer@A2", "qa-engineer@A2"]'::jsonb, 'Dev bên mình đang chạy 3 dự án cùng lúc, không ai nhớ hết các buổi họp đâu. File của bạn phải tự nói được mọi thứ.', 'Dự án đầu tiên của bạn ở agency xong rồi. Tuần sau có dự án mới, ngành khác hẳn. Quen dần đi nhé!', '[{"type": "character", "id": "frontend-developer"}, {"type": "term", "name": "Design System", "url": "https://academy.telos.vn/design-system-la-gi/"}]'::jsonb, true, null, '{"en": {"title": "Handoff and sign-off", "offer_text": "Our developers are running 3 projects at once, nobody remembers every meeting. Your file has to explain everything on its own.", "done_text": "Your first agency project is done. Next week there''s a new one, in a completely different industry. You''ll get used to it!"}}'::jsonb)
insert into tm_quest_steps (id, quest_id, sort_order, type, target, task_text, line_text, secs, i18n) values
  ('small-01-s1', 'small-01', 1, 'talk', 'tech-lead@P2', 'Hỏi Tech Lead phần nào của onboarding khó làm', 'Bước tải ảnh đại diện hơi nặng. Nếu bỏ được, team làm nhanh hơn 3 ngày.', null, '{"en": {"task_text": "Ask the Tech Lead which part of onboarding is hard to build", "line_text": "The profile photo upload step is a bit heavy. If we drop it, the team ships 3 days faster."}}'::jsonb),
  ('small-01-s2', 'small-01', 2, 'work', null, 'Về chỗ ngồi, vẽ wireframe onboarding', 'Wireframe gọn hơn nhiều khi bỏ bước ảnh đại diện. Gửi mình xem nhé!', 5, '{"en": {"task_text": "Go back to your desk and draw the onboarding wireframe", "line_text": "The wireframe is much leaner without the profile photo step. Send it over!"}}'::jsonb),
  ('small-02-s1', 'small-02', 1, 'talk', 'business-analyst@P3', 'Hỏi Business Analyst về yêu cầu kinh doanh', 'Người dùng thấy giá trị trong 3 phút đầu thì tỷ lệ nâng cấp cao gấp đôi. Onboarding phải dẫn tới đó.', null, '{"en": {"task_text": "Ask the Business Analyst about the business requirements", "line_text": "When users see value in the first 3 minutes, the upgrade rate doubles. Onboarding has to lead there."}}'::jsonb),
  ('small-03-s1', 'small-03', 1, 'talk', 'account-manager@P3', 'Hỏi Account Manager khách hàng than phiền gì', 'Khách doanh nghiệp muốn mời cả nhóm ngay khi đăng ký. Hiện phải làm sau, rất rối.', null, '{"en": {"task_text": "Ask the Account Manager what customers complain about", "line_text": "Business customers want to invite their whole team right at sign-up. Right now they have to do it later, and it''s confusing."}}'::jsonb),
  ('small-03-s2', 'small-03', 2, 'talk', 'user@P5', 'Ra Pantry hỏi trực tiếp một người dùng', 'Mình đăng ký xong mà không biết bấm vào đâu tiếp. Phải mò một lúc mới thấy.', null, '{"en": {"task_text": "Go to the Pantry and ask a user directly", "line_text": "I finished signing up and had no idea what to tap next. It took me a while to find it."}}'::jsonb),
  ('small-04-s1', 'small-04', 1, 'work', null, 'Về máy hoàn thiện file Figma và prototype', 'File xong rồi đó. Giờ bạn giải thích các trạng thái cho QA nhé.', 5, '{"en": {"task_text": "Go back to your computer and finish the Figma file and prototype", "line_text": "The file is done. Now walk QA through the states."}}'::jsonb),
  ('small-04-s2', 'small-04', 2, 'talk', 'qa-engineer@P2', 'Giải thích các trạng thái lỗi cho QA', 'Rõ rồi. Mình sẽ viết test case cho cả trạng thái mất mạng nữa.', null, '{"en": {"task_text": "Walk QA through the error states", "line_text": "Got it. I''ll write test cases for the offline state too."}}'::jsonb),
  ('small-05-s1', 'small-05', 1, 'present', null, 'Trình bày onboarding mới trên TV phòng họp', 'Cả phòng vỗ tay. CEO giơ tay muốn góp ý.', 6, '{"en": {"task_text": "Present the new onboarding on the meeting room TV", "line_text": "The whole room applauds. The CEO raises a hand to give feedback."}}'::jsonb),
  ('small-05-s2', 'small-05', 2, 'talk', 'ceo@P3', 'Hỏi ý kiến CEO', 'Rất rõ ràng. Mình thích việc người dùng thấy kết quả ngay ở bước 2. Ra mắt thôi!', null, '{"en": {"task_text": "Ask the CEO for feedback", "line_text": "Very clear. I like that users see a result right at step 2. Let''s ship it!"}}'::jsonb),
  ('large-01-s1', 'large-01', 1, 'talk', 'tech-lead@R03', 'Hỏi Tech Lead ước lượng effort', 'Khoảng 8 điểm. Nếu dùng lại component có sẵn trong Design System thì còn 5.', null, '{"en": {"task_text": "Ask the Tech Lead for an effort estimate", "line_text": "About 8 points. If we reuse existing Design System components, it''s 5."}}'::jsonb),
  ('large-01-s2', 'large-01', 2, 'work', null, 'Về chỗ ngồi, phác wireframe đầu tiên', 'Bản phác đầu tiên đã có. Story này vào sprint được rồi.', 5, '{"en": {"task_text": "Go back to your desk and sketch the first wireframe", "line_text": "The first sketch is ready. This story can go into the sprint."}}'::jsonb),
  ('large-02-s1', 'large-02', 1, 'talk', 'data-analyst@R07', 'Sang Data & Analytics xin số liệu funnel', 'Đây: 42% người dùng bỏ đi ở bước chọn sở thích. Đó là chỗ đáng sửa nhất.', null, '{"en": {"task_text": "Go to Data & Analytics for the funnel numbers", "line_text": "Here: 42% of users leave at the interest-picker step. That''s the place most worth fixing."}}'::jsonb),
  ('large-03-s1', 'large-03', 1, 'talk', 'ux-design-engineer@R05', 'Hỏi UX Design Engineer về component Chip', 'Chip có sẵn 3 trạng thái và đã có code. Bạn chỉ cần thêm trạng thái "đã chọn" có icon.', null, '{"en": {"task_text": "Ask the UX Design Engineer about the Chip component", "line_text": "Chip already has 3 states and the code exists. You only need to add a \"selected\" state with an icon."}}'::jsonb),
  ('large-04-s1', 'large-04', 1, 'present', null, 'Trình bày wireframe trên màn hình Critique', 'Mọi người đã xem xong. Giờ đi lấy góp ý từng người nhé.', 5, '{"en": {"task_text": "Present your wireframes on the Critique screen", "line_text": "Everyone has seen it. Now go get feedback from each person."}}'::jsonb),
  ('large-04-s2', 'large-04', 2, 'talk', 'product-designer@R02', 'Lấy góp ý từ Product Designer', 'Bước 2 có hai nút chính cạnh nhau, người dùng sẽ phân vân. Giữ một nút chính thôi.', null, '{"en": {"task_text": "Get feedback from the Product Designer", "line_text": "Step 2 has two primary buttons side by side, users will hesitate. Keep just one primary button."}}'::jsonb),
  ('large-04-s3', 'large-04', 3, 'talk', 'ux-designer@R04', 'Lấy góp ý từ UX Designer', 'Nên cho phép bỏ qua bước chọn sở thích. Đừng ép người dùng.', null, '{"en": {"task_text": "Get feedback from the UX Designer", "line_text": "Let people skip the interest-picker step. Don''t force users."}}'::jsonb),
  ('large-05-s1', 'large-05', 1, 'talk', 'user@R11', 'Nhờ User thử luồng onboarding và quan sát', 'Ủa, muốn bỏ qua bước này thì bấm ở đâu? À… cái chữ mờ mờ này hả. Mình tưởng nó bị khoá.', null, '{"en": {"task_text": "Ask the User to try the onboarding flow and observe", "line_text": "Hmm, where do I tap to skip this step? Oh… this faded text? I thought it was disabled."}}'::jsonb),
  ('large-05-s2', 'large-05', 2, 'talk', 'product-manager@R03', 'Chốt vấn đề vừa thấy với PM', 'Bạn thấy không? Người dùng không nhận ra nút "Bỏ qua" vì nó quá mờ.', null, '{"en": {"task_text": "Confirm the problem you just saw with the PM", "line_text": "See that? The user didn''t notice the \"Skip\" button because it''s too faint."}}'::jsonb),
  ('large-06-s1', 'large-06', 1, 'work', null, 'Về máy chuẩn bị spec và prototype', 'Spec có đủ trạng thái lỗi và trạng thái tải. Giải thích cho QA nhé.', 5, '{"en": {"task_text": "Go back to your computer and prepare the spec and prototype", "line_text": "The spec covers the error and loading states. Walk QA through it."}}'::jsonb),
  ('large-06-s2', 'large-06', 2, 'talk', 'qa-engineer@R03', 'Giải thích các trạng thái cho QA', 'Rõ rồi. Mình sẽ test thêm trường hợp mạng yếu và màn hình nhỏ.', null, '{"en": {"task_text": "Walk QA through the states", "line_text": "Got it. I''ll also test weak network and small screens."}}'::jsonb),
  ('large-07-s1', 'large-07', 1, 'present', null, 'Demo onboarding trên TV phòng họp', 'Demo rất mượt. Marketing và Customer Success đều có ý kiến.', 6, '{"en": {"task_text": "Demo the onboarding on the meeting room TV", "line_text": "A smooth demo. Marketing and Customer Success both have comments."}}'::jsonb),
  ('large-07-s2', 'large-07', 2, 'talk', 'growth-manager@R10', 'Nghe phản hồi từ Growth Manager', 'Mình muốn thêm bước mời bạn bè ngay cuối onboarding. Có làm được không?', null, '{"en": {"task_text": "Hear feedback from the Growth Manager", "line_text": "I''d like an invite-a-friend step right at the end of onboarding. Can we do that?"}}'::jsonb),
  ('large-07-s3', 'large-07', 3, 'talk', 'csm@R10', 'Nghe phản hồi từ Customer Success', 'Khách hàng sẽ rất thích. Họ hỏi chuyện này mỗi tuần.', null, '{"en": {"task_text": "Hear feedback from Customer Success", "line_text": "Customers will love it. They ask about this every week."}}'::jsonb),
  ('agency-01-s1', 'agency-01', 1, 'work', null, 'Về máy dựng nhanh mockup màn hình đặt lịch', 'Nhìn được đó! Có hình thật thì khách dễ hình dung hơn hẳn slide toàn chữ.', 5, '{"en": {"task_text": "Go back to your computer and quickly mock up the booking screen", "line_text": "That looks good! A real screen helps the client picture it far better than slides full of text."}}'::jsonb),
  ('agency-01-s2', 'agency-01', 2, 'talk', 'ceo@A6', 'Hỏi Founder nên nhấn điểm gì khi gặp khách', 'Đừng khoe nhiều tính năng. Cho họ thấy hội viên đặt được lịch trong 3 bước là đủ.', null, '{"en": {"task_text": "Ask the Founder what to emphasise with the client", "line_text": "Don''t show off lots of features. Showing members can book a class in 3 steps is enough."}}'::jsonb),
  ('agency-02-s1', 'agency-02', 1, 'talk', 'client@A4', 'Hỏi Client mục tiêu của dự án', 'Bên anh có 12 phòng tập. Hội viên toàn gọi điện đặt lịch nên lễ tân quá tải. Anh muốn sau 3 tháng, 70% lượt đặt lịch đi qua app.', null, '{"en": {"task_text": "Ask the Client about the project goals", "line_text": "We have 12 gyms. Members all phone in to book, so reception is overloaded. In 3 months I want 70% of bookings to go through the app."}}'::jsonb),
  ('agency-02-s2', 'agency-02', 2, 'talk', 'project-manager@A3', 'Chốt lại ghi chú với Project Manager', 'Mình ghi nhận: mục tiêu là giảm cuộc gọi đặt lịch. Mọi màn hình sau này phải phục vụ điều đó.', null, '{"en": {"task_text": "Go over your notes with the Project Manager", "line_text": "Noted: the goal is fewer booking calls. Every screen from now on has to serve that."}}'::jsonb),
  ('agency-03-s1', 'agency-03', 1, 'talk', 'business-analyst@A3', 'Hỏi Business Analyst danh sách màn hình', 'Khách liệt kê 24 màn hình. Nhưng để hội viên đặt được lịch thì chỉ cần 9 màn hình là chạy được.', null, '{"en": {"task_text": "Ask the Business Analyst for the list of screens", "line_text": "The client listed 24 screens. But for members to book a class, 9 screens are enough to get it running."}}'::jsonb),
  ('agency-03-s2', 'agency-03', 2, 'talk', 'tech-lead@A2', 'Sang Dev team hỏi Tech Lead cái nào làm kịp', '9 màn hình thì kịp 8 tuần. Riêng thanh toán online nên để giai đoạn 2, tích hợp cổng thanh toán mất ít nhất 3 tuần.', null, '{"en": {"task_text": "Go to the Dev team and ask the Tech Lead what fits in time", "line_text": "9 screens fit in 8 weeks. Online payments should wait for phase 2, integrating a payment gateway takes at least 3 weeks."}}'::jsonb),
  ('agency-04-s1', 'agency-04', 1, 'work', null, 'Về máy làm concept luồng đặt lịch', 'Xong concept rồi à? Trước khi mình xem, bạn hỏi Graphic Designer về nhận diện của khách đã.', 5, '{"en": {"task_text": "Go back to your computer and make a concept for the booking flow", "line_text": "Concept done? Before I look, ask the Graphic Designer about the client''s brand identity."}}'::jsonb),
  ('agency-04-s2', 'agency-04', 2, 'talk', 'graphic-designer@A1', 'Hỏi Graphic Designer về màu thương hiệu của khách', 'Logo khách màu cam đậm. Bạn chỉ dùng cam cho nút chính thôi, đừng phủ cả màn hình, chói lắm.', null, '{"en": {"task_text": "Ask the Graphic Designer about the client''s brand colours", "line_text": "The client''s logo is a deep orange. Use orange only for the primary button, don''t cover the whole screen, it''s too loud."}}'::jsonb),
  ('agency-05-s1', 'agency-05', 1, 'present', null, 'Trình bày concept trên TV phòng họp', 'Bạn vừa trình bày xong. Khách gật gù, nhưng có vẻ còn muốn nói gì đó.', 6, '{"en": {"task_text": "Present the concept on the meeting room TV", "line_text": "You''ve just finished presenting. The client nods, but seems to want to say something."}}'::jsonb),
  ('agency-05-s2', 'agency-05', 2, 'talk', 'client@A4', 'Nghe phản hồi của Client', 'Luồng đặt lịch thì anh thích. Nhưng trang chủ trống quá. Em thêm banner khuyến mãi, tin tức, rồi bảng xếp hạng hội viên nữa nhé.', null, '{"en": {"task_text": "Hear the Client''s feedback", "line_text": "I like the booking flow. But the home screen is too empty. Add promo banners, news, and a member leaderboard too."}}'::jsonb),
  ('agency-06-s1', 'agency-06', 1, 'talk', 'project-manager@A3', 'Đừng nhận lời vội. Về hỏi Project Manager', 'Hai phần đó nằm ngoài hợp đồng, cộng lại khoảng 4 tuần nữa. Mình sẽ báo giá bổ sung. Khách đồng ý thì mới làm.', null, '{"en": {"task_text": "Don''t say yes yet. Go ask the Project Manager", "line_text": "Those two parts are outside the contract, about 4 more weeks combined. I''ll send an additional quote. We only build it if the client agrees."}}'::jsonb),
  ('agency-06-s2', 'agency-06', 2, 'talk', 'account-manager@A3', 'Nhờ Account Manager nói lại với khách', 'Để mình nói. Bạn cứ giữ thái độ vui vẻ: đừng từ chối thẳng, mà cũng đừng hứa.', null, '{"en": {"task_text": "Ask the Account Manager to talk to the client", "line_text": "Let me handle it. Just stay friendly: don''t refuse outright, but don''t promise either."}}'::jsonb),
  ('agency-07-s1', 'agency-07', 1, 'talk', 'user@A5', 'Ra Pantry nhờ User dùng thử trang chủ', 'Mình mở app là muốn đặt lịch ngay. Mấy cái banner này che mất nút, mình tưởng quảng cáo nên lướt qua luôn.', null, '{"en": {"task_text": "Go to the Pantry and ask the User to try the home screen", "line_text": "When I open the app I want to book right away. These banners hide the button, I thought they were ads so I just scrolled past."}}'::jsonb),
  ('agency-07-s2', 'agency-07', 2, 'talk', 'client@A4', 'Mang kết quả cho Client xem', 'Hội viên nói vậy thật à? Thôi được, banner cho xuống dưới, nút đặt lịch để trên cùng.', null, '{"en": {"task_text": "Show the results to the Client", "line_text": "A member really said that? Fine, move the banners down and put the booking button at the top."}}'::jsonb),
  ('agency-08-s1', 'agency-08', 1, 'work', null, 'Về máy chuẩn bị spec và prototype', 'Spec đủ các trạng thái rồi. Giờ bạn giải thích cho Frontend nhé.', 5, '{"en": {"task_text": "Go back to your computer and prepare the spec and prototype", "line_text": "The spec covers all the states. Now walk the Frontend developer through it."}}'::jsonb),
  ('agency-08-s2', 'agency-08', 2, 'talk', 'frontend-developer@A2', 'Giải thích spec cho Frontend Developer', 'Rõ rồi. Mình dùng lại bộ component của dự án trước, chỉ đổi màu theo thương hiệu khách.', null, '{"en": {"task_text": "Walk the Frontend Developer through the spec", "line_text": "Got it. I''ll reuse the component set from the last project and just swap in the client''s brand colours."}}'::jsonb),
  ('agency-08-s3', 'agency-08', 3, 'talk', 'client@A4', 'Mời Client nghiệm thu sản phẩm', 'App chạy đúng như bản thiết kế. Anh ký nghiệm thu. Giai đoạn 2 anh làm tiếp với bên em.', null, '{"en": {"task_text": "Invite the Client to sign off the product", "line_text": "The app works exactly like the design. I''m signing off. We''ll do phase 2 with your team too."}}'::jsonb)
